(function () {
  function ready(fn) {
    if (document.readyState !== "loading") {
      fn();
      return;
    }
    document.addEventListener("DOMContentLoaded", fn);
  }

  ready(function () {
    var nav = document.getElementById("site-nav");
    var masthead = document.querySelector(".masthead");
    var mobileQuery = window.matchMedia("(max-width: 640px)");

    if (nav) {
      var button = nav.querySelector(".mobile-nav-toggle");
      var label = nav.querySelector(".mobile-nav-toggle__label");
      var panel = document.getElementById("mobile-navigation");
      var backdrop = document.querySelector(".mobile-nav-backdrop");
      var brand = document.querySelector(".mobile-nav-brand");
      var menuLinks = panel ? Array.prototype.slice.call(panel.querySelectorAll("a")) : [];

      function syncMobileLayers() {
        if (!panel || !backdrop) return;
        if (mobileQuery.matches) {
          document.body.appendChild(backdrop);
          document.body.appendChild(panel);
        } else if (panel.parentNode !== nav) {
          nav.appendChild(panel);
          nav.appendChild(backdrop);
        }
      }

      function syncNavTop() {
        if (!masthead) return;
        var navTop = Math.max(0, Math.ceil(masthead.getBoundingClientRect().bottom) - 1);
        document.documentElement.style.setProperty("--mobile-nav-top", navTop + "px");
      }

      function setMenu(open, returnFocus) {
        if (!button || !panel) return;
        var isMobile = mobileQuery.matches;
        open = Boolean(open && isMobile);
        if (open) {
          syncMobileLayers();
          syncNavTop();
        }
        nav.classList.toggle("menu-open", open);
        document.documentElement.classList.toggle("mobile-nav-open", open);
        button.setAttribute("aria-expanded", open ? "true" : "false");
        button.setAttribute("aria-label", open ? "Close navigation" : "Open navigation");
        panel.setAttribute("aria-hidden", isMobile && !open ? "true" : "false");
        if (label) label.textContent = open ? "Close" : "Menu";
        if (!open && returnFocus) button.focus();
      }

      syncMobileLayers();
      syncNavTop();
      window.addEventListener("resize", function () {
        if (!mobileQuery.matches) setMenu(false, false);
        syncMobileLayers();
        syncNavTop();
      }, { passive: true });

      if (button && panel && backdrop) {
        panel.setAttribute("aria-hidden", mobileQuery.matches ? "true" : "false");

        button.addEventListener("click", function () {
          setMenu(button.getAttribute("aria-expanded") !== "true", false);
        });

        backdrop.addEventListener("click", function () {
          setMenu(false, true);
        });

        menuLinks.forEach(function (link) {
          link.addEventListener("click", function () {
            setMenu(false, false);
          });
        });

        if (brand) {
          brand.addEventListener("click", function () {
            setMenu(false, false);
          });
        }

        document.addEventListener("keydown", function (event) {
          if (!nav.classList.contains("menu-open")) return;
          if (event.key === "Escape") {
            event.preventDefault();
            setMenu(false, true);
            return;
          }
          if (event.key !== "Tab") return;
          var focusable = [button].concat(menuLinks);
          var first = focusable[0];
          var last = focusable[focusable.length - 1];
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
          } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
          }
        });
      }
    }

    var urls = document.querySelector(".author__urls");
    function syncAuthorUrls() {
      if (!urls) return;
      urls.style.display = window.innerWidth > 925 ? "block" : "none";
    }
    syncAuthorUrls();
    window.addEventListener("resize", syncAuthorUrls, { passive: true });

    var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    var reveal = document.querySelectorAll(".reveal,.publication-card,.timeline__entry");
    if (reduce || !("IntersectionObserver" in window)) {
      reveal.forEach(function (item) {
        item.classList.add("is-visible");
      });
    } else {
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.08, rootMargin: "0px 0px -28px" });
      reveal.forEach(function (item) {
        observer.observe(item);
      });
    }

    var links = document.querySelectorAll('.greedy-nav a[href*="#"]');
    var sections = [];
    links.forEach(function (link) {
      var hash = link.getAttribute("href").split("#")[1];
      var section = hash && document.getElementById(hash);
      if (section) sections.push({ link: link, section: section });
    });

    function activeLink() {
      var current = null;
      sections.forEach(function (item) {
        if (item.section.getBoundingClientRect().top <= 150) current = item;
      });
      links.forEach(function (link) {
        link.removeAttribute("aria-current");
      });
      if (current) current.link.setAttribute("aria-current", "true");
    }

    if (sections.length) {
      activeLink();
      window.addEventListener("scroll", activeLink, { passive: true });
      window.addEventListener("hashchange", function () {
        requestAnimationFrame(activeLink);
      });
    }
  });
})();
